import{_ as n,a0 as s,w as i,s as d,ao as l,I as p,x as t,a1 as a,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"如何在 Linux 中整理磁盤碎片 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中整理磁盤碎片 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中整理磁盤碎片 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中整理磁盤碎片 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150901 How to Defragment Linux Systems","title":"如何在 Linux 中整理磁盤碎片","tag":"201509","desc":""},"relativePath":"201509/20150901 How to Defragment Linux Systems.md","filePath":"[post].md"}'),u={name:"201509/20150901 How to Defragment Linux Systems.md"};function c(m,e,f,g,x,h){const o=s("Link");return i(),d("div",null,[e[13]||(e[13]=l(`<h1 id="如何在-linux-中整理磁盤碎片" tabindex="-1">如何在 Linux 中整理磁盤碎片 <a class="header-anchor" href="#如何在-linux-中整理磁盤碎片" aria-label="Permalink to “如何在 Linux 中整理磁盤碎片”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/defragment-linux-featured.png" alt=""></p><p>有一神話是 linux 的磁盤從來不需要整理碎片。在大多數情況下這是真的，大多數因為是使用的是優秀的日誌系統（ext2、3、4等等）來處理文件系統。然而，在一些特殊情況下，碎片仍舊會產生。如果正巧發生在你身上，解決方法很簡單。</p><h3 id="什麼是磁盤碎片" tabindex="-1">什麼是磁盤碎片 <a class="header-anchor" href="#什麼是磁盤碎片" aria-label="Permalink to “什麼是磁盤碎片”">​</a></h3><p>文件系統會按塊更新文件，如果這些塊沒有連成一整塊而是分佈在磁盤的各個角落中時，就會形成磁盤碎片。這對於 FAT 和 FAT32 文件系統而言是這樣的。在 NTFS 中這種情況有所減輕，但在 Linux（extX）中卻幾乎不會發生。下面是原因：</p><p>在像 FAT 和 FAT32 這類文件系統中，文件緊挨着寫入到磁盤中。文件之間沒有空間來用於增長或者更新：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/defragment-linux-fragmented.png" alt=""></p><p>NTFS 中在文件之間保留了一些空間，因此有空間進行增長。但因塊之間的空間是有限的，碎片也會隨着時間出現。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/defragment-linux-ntfs.png" alt=""></p><p>Linux 的日誌型文件系統採用了一個不同的方案。與文件相互挨着不同，每個文件分佈在磁盤的各處，每個文件之間留下了大量的剩餘空間。這就給文件更新和增長留下了很大的空間，碎片很少會發生。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/defragment-linux-journal.png" alt=""></p><p>此外，碎片一旦出現了，大多數 Linux 文件系統會嘗試將文件和塊重新連續起來。</p><h3 id="linux-中的磁盤整理" tabindex="-1">Linux 中的磁盤整理 <a class="header-anchor" href="#linux-中的磁盤整理" aria-label="Permalink to “Linux 中的磁盤整理”">​</a></h3><p>除非你用的是一個很小的硬盤或者空間不夠了，不然 Linux 很少會需要磁盤整理。一些可能需要磁盤整理的情況包括：</p><ul><li>如果你編輯的是大型視頻文件或者 RAW 照片，但磁盤空間有限</li><li>如果你使用一個老式硬件，如舊筆記本，你的硬盤會很小</li><li>如果你的磁盤開始滿了（大約使用了85%）</li><li>如果你的家目錄中有許多小分區</li></ul><p>最好的解決方案是購買一個大硬盤。如果不可能，磁盤碎片整理就很有用了。</p><h3 id="如何檢查碎片" tabindex="-1">如何檢查碎片 <a class="header-anchor" href="#如何檢查碎片" aria-label="Permalink to “如何檢查碎片”">​</a></h3><p><code>fsck</code> 命令會為你做這個，換句話説，如果你可以在 LiveCD 中運行它，那麼就可以用於<strong>所有卸載的分區</strong>。</p><p>這一點很重要：<strong>在已經掛載的分區中運行 fsck 將會嚴重危害到你的數據和磁盤</strong>。</p><p>你已經被警告過了。開始之前，先做一個完整的備份。</p><p><strong>免責聲明</strong>： 本文的作者與本站將不會對您的文件、數據、系統或者其他損害負責。你需要自己承擔風險。如果你繼續，你需要接受並瞭解這點。</p><p>你應該啓動到一個 live 會話中（如使用安裝磁盤，系統救援CD等）並在你<strong>卸載</strong>的分區上運行 <code>fsck</code> 。要檢查是否有任何問題，請在使用 root 權限運行下面的命令：</p><pre><code>fsck -fn [/path/to/your/partition]
</code></pre><p>您可以運行以下命令找到分區的路徑</p><pre><code>sudo fdisk -l
</code></pre><p>有一個在已掛載的分區中運行 <code>fsck</code>（相對）安全的方法是使用<code>-n</code>開關。這會對分區進行只讀文件系統檢查，而不會寫入任何東西。當然，這並不能保證十分安全，你應該在創建備份之後進行。在 ext2 中，運行</p><pre><code>sudo fsck.ext2 -fn /path/to/your/partition
</code></pre><p>這會產生大量的輸出，大多數錯誤信息的原因是分區已經掛載了。最後會給出一個碎片相關的信息。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/defragment-linux-fsck.png" alt=""></p><p>如果碎片率大於 20% 了，那麼你應該開始整理你的磁盤碎片了。</p><h3 id="如何簡單地在-linux-中整理碎片" tabindex="-1">如何簡單地在 Linux 中整理碎片 <a class="header-anchor" href="#如何簡單地在-linux-中整理碎片" aria-label="Permalink to “如何簡單地在 Linux 中整理碎片”">​</a></h3><p>你要做的是備份你<strong>所有</strong>的文件和數據到另外一塊硬盤中（手動<strong>複製</strong>他們），格式化分區，然後重新複製回去（不要使用備份軟件）。日誌型文件系統會把它們作為新的文件，並將它們整齊地放置到磁盤中而不產生碎片。</p><p>要備份你的文件，運行</p><pre><code>cp -afv [/path/to/source/partition]/* [/path/to/destination/folder]
</code></pre><p>記住星號（*）是很重要的。</p><p>注意：通常認為複製大文件或者大量文件，使用 <code>dd</code> 或許是最好的。這是一個非常底層的操作，它會複製一切，包含空閒的空間甚至是留下的垃圾。這不是我們想要的，因此這裏最好使用 <code>cp</code>。</p><p>現在你只需要刪除源文件。</p><pre><code>sudo rm -rf [/path/to/source/partition]/*
</code></pre><p><strong>可選</strong>：你可以使用如下命令將空閒空間用零填充。也可以用格式化來達到這點，但是如果你並沒有複製整個分區而僅僅是複製大文件（它通常會形成碎片）的話，就不應該使用格式化的方法了。</p><pre><code>sudo dd if=/dev/zero of=[/path/to/source/partition]/temp-zero.txt
</code></pre><p>等待它結束。你可以用 <code>pv</code> 來監測進度。</p><pre><code>sudo apt-get install pv
sudo pv -tpreb | of=[/path/to/source/partition]/temp-zero.txt
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/defragment-linux-dd.png" alt=""></p><p>這就完成了，只要刪除這個用於填充的臨時文件就行。</p><pre><code>sudo rm [/path/to/source/partition]/temp-zero.txt
</code></pre><p>待你清零了空閒空間（或者跳過了這步）。重新複製迴文件，將第一個<code>cp</code>命令翻轉一下：</p><pre><code>cp -afv [/path/to/original/destination/folder]/* [/path/to/original/source/partition]
</code></pre><h3 id="使用-e4defrag" tabindex="-1">使用 e4defrag <a class="header-anchor" href="#使用-e4defrag" aria-label="Permalink to “使用 e4defrag”">​</a></h3><p>如果你想要簡單的方法，安裝 <code>e2fsprogs</code>，</p><pre><code>sudo apt-get install e2fsprogs
</code></pre><p>用 root 權限在分區中運行 <code>e4defrag</code>。如果你不想或不能卸載該分區，你可以使用它的掛載點而不是路徑。要整理整個系統的碎片，運行：</p><pre><code>sudo e4defrag  /
</code></pre><p>在掛載的情況下不保證成功（你也應該在它運行時不要使用你的系統），但是它比複製全部文件再重新複製回來簡單多了。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>linux 系統中由於它的日誌型文件系統有效的數據處理很少會出現碎片。如果你因任何原因產生了碎片，簡單的方法是重新分配你的磁盤，如複製出去所有文件並複製回來，或者使用<code>e4defrag</code>。然而重要的是保證你數據的安全，因此在進行任何可能影響你全部或者大多數文件的操作之前，確保你的文件已經被備份到了另外一個安全的地方去了。</p><hr>`,56)),p("p",null,[e[1]||(e[1]=t("via: ",-1)),a(o,{href:"https://www.maketecheasier.com/defragment-linux/"},{default:r(()=>[...e[0]||(e[0]=[t("https://www.maketecheasier.com/defragment-linux/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=t("作者：",-1)),a(o,{href:"https://www.maketecheasier.com/author/attilaorosz/"},{default:r(()=>[...e[2]||(e[2]=[t("Attila Orosz",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),a(o,{href:"https://github.com/geekpi"},{default:r(()=>[...e[3]||(e[3]=[t("geekpi",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),a(o,{href:"https://github.com/wxy"},{default:r(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=t("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創編譯，",-1)),a(o,{href:"https://linux.cn/"},{default:r(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const T=n(u,[["render",c]]);export{L as __pageData,T as default};
